window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2a2ca39654b2786d"]={"versions": [{"id": "FIG-2a2ca39654b2786d", "releases": ["R1.3.0", "R1.5.1", "R17-10_R1.2.0", "R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Abhängigkeitsdiagramm der AUTOSAR-Standards. Das Diagramm modelliert die geschichtete Standardisierungsarchitektur zwischen plattformspezifischen Standards (<code>Classic Platform</code>, <code>Adaptive Platform</code>) und den gemeinsamen Basisspezifikationen (<code>Foundation</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Classic Platform</strong>: Spezifikationsblock für die klassische Steuergerätearchitektur (tief eingebettete ECUs).\n</li><li><strong>Adaptive Platform</strong>: Spezifikationsblock für die serviceorientierte Hochleistungsplattform (POSIX-basiert).\n</li><li><strong>Foundation</strong>: Grundlegender Spezifikationsblock mit plattformübergreifend geteilten Anforderungen, Protokollen und Datenmodellen.\n</li><li><strong>Abhängigkeitsbeziehungen</strong>: Zwei gerichtete Pfeile weisen von <code>Classic Platform</code> sowie von <code>Adaptive Platform</code> nach unten auf <code>Foundation</code>, was eine direkte funktionale und semantische Abhängigkeit beider Plattformen von den Basiskonzepten der Foundation darstellt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architektur- und Abhängigkeitsmodell ohne Laufzeitverhalten oder Protokollsequenzen. Die Pfeile kennzeichnen Spezifikations- und Verwendungsabhängigkeiten bei der Normierung und Implementierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Spezifikationen der <code>Classic Platform</code> und <code>Adaptive Platform</code> bauen auf den Vorgaben der <code>Foundation</code> auf. Änderungen an <code>Foundation</code>-Spezifikationen wirken sich direkt auf beide Zielplattformen aus, wohingegen zwischen Classic und Adaptive Platform im Diagramm keine direkte Querverbindung existiert.</p>"}, {"id": "FIG-9dea85914226d4d4", "releases": ["R17-03_R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Abhängigkeitsdiagramm der AUTOSAR-Standards. Das Diagramm modelliert die vertikale Schichtung und Abhängigkeiten zwischen Teststandards (<code>Acceptance Tests</code>), plattformspezifischen Standards (<code>Classic Platform</code>, <code>Adaptive Platform</code>) sowie den gemeinsamen Basisspezifikationen (<code>Foundation</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Acceptance Tests</strong>: Spezifikationsblock für plattformbezogene Akzeptanztest-Spezifikationen auf Systemebene.\n</li><li><strong>Classic Platform</strong>: Spezifikationsblock für die klassische AUTOSAR-Steuergerätearchitektur.\n</li><li><strong>Adaptive Platform</strong>: Spezifikationsblock für die adaptive, serviceorientierte AUTOSAR-Plattform.\n</li><li><strong>Foundation</strong>: Übergreifender Basis-Spezifikationsblock für gemeinsame Standards.\n</li><li><strong>Abhängigkeitsbeziehungen</strong>: Gerichteter Pfeil von <code>Acceptance Tests</code> nach unten auf <code>Classic Platform</code>; gerichtete Pfeile von <code>Classic Platform</code> sowie <code>Adaptive Platform</code> nach unten auf <code>Foundation</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architektur- und Abhängigkeitsmodell ohne Laufzeitverhalten oder Protokollsequenzen. Die Pfeile kennzeichnen Spezifikations- und Verwendungsabhängigkeiten bei der Normierung und Implementierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikationen der <code>Acceptance Tests</code> hängen direkt von den Spezifikationen der <code>Classic Platform</code> ab und verifizieren diese gegen die Plattformdefinition. <code>Classic Platform</code> und <code>Adaptive Platform</code> referenzieren und nutzen verbindlich die Spezifikationen der <code>Foundation</code>. Zwischen <code>Acceptance Tests</code> und <code>Adaptive Platform</code> besteht im Diagramm keine dokumentierte Abhängigkeit.</p>"}], "trans": [{"from": "FIG-2a2ca39654b2786d", "to": "FIG-9dea85914226d4d4", "fr": "R1.5.1", "tr": "R17-03_R1.1.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ergänzung des Blocks <code>Acceptance Tests</code> oberhalb von <code>Classic Platform</code>.\n</li><li>Ergänzung einer gerichteten Abhängigkeit (Pfeil) von <code>Acceptance Tests</code> nach unten auf <code>Classic Platform</code>.\n</li></ul>"}, {"from": "FIG-9dea85914226d4d4", "to": "FIG-2a2ca39654b2786d", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Entfernung des Blocks <code>Acceptance Tests</code> oberhalb von <code>Classic Platform</code>.\n</li><li>Entfernung der gerichteten Abhängigkeit von <code>Acceptance Tests</code> auf <code>Classic Platform</code>.\n</li></ul>"}]};
